// ===== loadLeadStats — 拉后端 /api/leads/stats，写入 state.leadStats =====
// opts: { scope?: 'self'|'employee'|'all', employeeId?: string, period?: 'today'|'week'|'month'|'custom', from?: string, to?: string }
// 员工/销售端默认 scope=self（后端按 session 推断），管理端默认 scope=all。
async function loadLeadStats(opts = {}) {
  const role = state.user?.role || "";
  const defaultScope = (role === "staff" || role === "sales") ? "self" : "all";
  const params = new URLSearchParams();
  const scope = opts.scope || defaultScope;
  if (scope) params.set("scope", scope);
  if (scope === "employee" && opts.employeeId) params.set("employeeId", opts.employeeId);
  if (opts.period) params.set("period", opts.period);
  if (opts.from) params.set("from", opts.from);
  if (opts.to) params.set("to", opts.to);
  state.leadStatsLoading = true;
  try {
    const stats = await api(`/api/leads/stats?${params.toString()}`);
    state.leadStats = stats || {};
  } catch (err) {
    state.leadStats = state.leadStats || {};
  } finally {
    state.leadStatsLoading = false;
  }
}

// 客资看板视图触发：根据当前角色 + 所有看板筛选条件拉一次 stats。
// T-L2/L3：把账号 / 平台 / 作品类型 / 状态 / 添加状态 / 日期范围一起传给后端，
// 保证"筛选后数量 = 列表实际条数"（AC-3.2）。
// 调用方式：进入视图时、任一筛选条件变化时调用；加载完成后 renderApp。
function refreshLeadStatsForCurrentView() {
  const role = state.user?.role || "";
  const opts = { period: "month" };
  if (role === "staff" || role === "sales") {
    opts.scope = "self";
  } else if (state.leadMonitorEmployeeFilter) {
    opts.scope = "employee";
    opts.employeeId = state.leadMonitorEmployeeFilter;
  } else {
    opts.scope = "all";
  }
  if (state.leadMonitorAccountFilter) opts.accountId = state.leadMonitorAccountFilter;
  if (state.leadMonitorPlatformFilter) opts.platform = state.leadMonitorPlatformFilter;
  if (state.leadMonitorPostTypeFilter) opts.postType = state.leadMonitorPostTypeFilter;
  if (state.leadMonitorStatusFilter) opts.status = state.leadMonitorStatusFilter;
  if (state.leadMonitorAddStatusFilter) opts.addStatus = state.leadMonitorAddStatusFilter;
  // 日期筛选：按天用 leadMonitorDate；按周用 leadMonitorWeek（ISO YYYY-Www）→ custom 模式
  if (state.leadMonitorMode === "day" && state.leadMonitorDate) {
    opts.period = "custom";
    opts.from = `${state.leadMonitorDate} 00:00:00`;
    const next = new Date(state.leadMonitorDate);
    next.setDate(next.getDate() + 1);
    opts.to = `${next.toISOString().slice(0, 10)} 00:00:00`;
  } else if (state.leadMonitorMode === "week" && state.leadMonitorWeek) {
    opts.period = "custom";
    const match = /^(\d{4})-W(\d{2})$/.exec(state.leadMonitorWeek);
    if (match) {
      const year = Number(match[1]);
      const week = Number(match[2]);
      // ISO 周一作为起点
      const jan4 = new Date(year, 0, 4);
      const jan4Day = jan4.getDay() || 7;
      const monday = new Date(jan4);
      monday.setDate(jan4.getDate() - (jan4Day - 1) + (week - 1) * 7);
      const sunday = new Date(monday);
      sunday.setDate(monday.getDate() + 7);
      const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")} 00:00:00`;
      opts.from = fmt(monday);
      opts.to = fmt(sunday);
    }
  }
  loadLeadStats(opts).then(() => {
    if (typeof renderApp === "function") renderApp();
  });
}


