// ===== L5454-L5461 deleteLead =====
async function deleteLead(id) {
  if (!window.confirm("确认删除该客资吗？")) return;
  await api(`/api/leads/${id}`, { method: "DELETE" });
  state.editingLeadId = state.editingLeadId === id ? "" : state.editingLeadId;
  await loadData();
  renderApp();
}


// ===== L5563-L5685 submitLead / submitSalesLead / submitLeadNote / submitSalesLocalProfile / toggleTomorrowFollowup / completeTomorrowFollowup / updateLeadBoardState / remindLead =====
async function submitLead(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  if (state.leadCaptureFile) {
    formData.set("captureImage", state.leadCaptureFile, state.leadCaptureFile.name || "lead-capture.png");
  }
  if (!String(formData.get("postId") || "")) {
    alert("请选择这条客资对应的作品。");
    return;
  }
  const id = String(formData.get("id") || "");
  formData.delete("id");
  await api(id ? `/api/leads/${id}` : "/api/leads", {
    method: id ? "PUT" : "POST",
    body: formData
  });
  // 提交成功后清理草稿（仅新建场景）
  if (!id && state.leadDraftId) {
    const draftId = state.leadDraftId;
    state.leadDraftId = null;
    state.pendingLeadCapture = null;
    resetLeadDraftContext();
    await deleteLeadDraftById(draftId);
  }
  clearPendingLeadCapture();
  state.editingLeadId = "";
  setFlash("success", id ? "客资已更新" : "客资已录入", "这条客资已经保存到后台数据库，下方记录和主管端监控都会同步更新。");
  await loadData();
  renderApp();
}

async function submitSalesLead(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const id = String(formData.get("id") || "");
  formData.delete("id");
  await api(`/api/leads/${id}`, {
    method: "PUT",
    body: formData
  });
  state.editingLeadId = "";
  setFlash("success", "销售反馈已更新", "这条客资的状态和跟进反馈已经保存，主管端刷新后会同步看到。");
  await loadData();
  renderApp();
}

async function submitLeadNote(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const id = String(formData.get("id") || "");
  formData.delete("id");
  await api(`/api/leads/${id}`, {
    method: "PUT",
    body: formData
  });
  state.editingLeadNoteId = "";
  setFlash("success", "客资备注已更新", "这条客资的备注已经保存，后续跟进和主管复盘时都能看到。");
  await loadData();
  renderApp();
}

function submitSalesLocalProfile(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const id = String(formData.get("id") || "");
  const customerLabel = String(formData.get("customerLabel") || "").trim();
  state.salesLeadLocalProfiles = {
    ...(state.salesLeadLocalProfiles || {}),
    [id]: {
      customerLabel
    }
  };
  saveSalesLeadLocalProfiles();
  state.editingSalesLeadProfileId = "";
  renderApp();
}

function toggleTomorrowFollowup(id, checked) {
  const next = new Set(state.salesTomorrowFollowupIds || []);
  if (checked) next.add(id);
  else next.delete(id);
  state.salesTomorrowFollowupIds = Array.from(next);
  if (!state.salesTomorrowFollowupIds.length) {
    state.salesTomorrowFollowupPanelOpen = false;
  }
  saveSalesTomorrowFollowupIds();
  renderApp();
}

function completeTomorrowFollowup(id) {
  state.salesTomorrowFollowupIds = (state.salesTomorrowFollowupIds || []).filter((item) => item !== id);
  if (!state.salesTomorrowFollowupIds.length) {
    state.salesTomorrowFollowupPanelOpen = false;
  }
  saveSalesTomorrowFollowupIds();
  renderApp();
}

async function updateLeadBoardState(id, patch) {
  const current = state.leads.find((item) => item.id === id);
  if (!current) return;
  const payload = {
    assignedSalesUserId: patch.assignedSalesUserId ?? current.assignedSalesUserId ?? "",
    assignedSalesUserName: patch.assignedSalesUserName ?? current.assignedSalesUserName ?? (state.user?.role === "sales" ? (state.user.employeeName || state.user.username || "") : ""),
    processStatus: patch.processStatus ?? current.processStatus ?? "not_contacted",
    addStatus: patch.addStatus ?? current.addStatus ?? "未添加",
    intention: patch.intention ?? current.intention ?? ""
  };
  if (patch.intentionLevel !== undefined) payload.intentionLevel = patch.intentionLevel;
  if (patch.nextFollowTime !== undefined) payload.nextFollowTime = patch.nextFollowTime || null;
  if (patch.followNote !== undefined) payload.followNote = patch.followNote;
  if (patch.followType !== undefined) payload.followType = patch.followType;
  if (state.user?.id) payload.actorUserId = state.user.id;
  if (state.user?.role === "sales" && !payload.assignedSalesUserName) {
    payload.assignedSalesUserName = state.user.employeeName || state.user.username || "";
    payload.assignedSalesUserId = state.user.id || "";
  }
  await api(`/api/leads/${id}/board`, {
    method: "PUT",
    body: JSON.stringify(payload)
  });
  setFlash("success", "客资状态已更新", "这条客资的处理状态已经同步到看板。");
  await loadData();
  renderApp();
}

async function remindLead(id, target) {
  await api(`/api/leads/${id}/remind`, {
    method: "POST",
    body: JSON.stringify({ target })
  });
  await loadData();
  setFlash("success", "提醒已发送", target === "sales" ? "请及时添加" : "微信未同意提醒已发送给运营");
  renderApp();
}

async function showLeadFollowTimeline(id) {
  const lead = state.leads.find((item) => item.id === id);
  if (!lead) return;
  let records = [];
  try {
    records = await api(`/api/leads/${id}/follow-records?limit=100`);
  } catch (err) {
    setFlash("warn", "时间线加载失败", err?.message || "请稍后重试");
    return;
  }
  const list = Array.isArray(records) ? records : [];
  const rowsHtml = list.length
    ? list.map((r) => `
        <li class="lead-timeline-item">
          <div class="lead-timeline-meta">
            <strong>${formatDate(r.createdAt) || "-"}</strong>
            <span class="muted">${r.followType || "微信"}</span>
          </div>
          <p>${(r.content || "").replace(/[<>]/g, "")}</p>
          ${r.nextFollowTime ? `<span class="muted">下次跟进：${formatNextFollowTime(r.nextFollowTime)}</span>` : ""}
        </li>
      `).join("")
    : `<li class="empty">暂无跟进记录</li>`;
  const overlay = document.createElement("div");
  overlay.className = "lead-timeline-overlay";
  overlay.innerHTML = `
    <div class="lead-timeline-drawer">
      <header>
        <h3>跟进时间线 · ${lead.nickname || lead.contactInfo || "未命名客资"}</h3>
        <button class="ghost js-close-timeline" type="button">关闭</button>
      </header>
      <ul class="lead-timeline-list">${rowsHtml}</ul>
    </div>
  `;
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay || e.target.classList.contains("js-close-timeline")) {
      overlay.remove();
    }
  });
  document.body.appendChild(overlay);
}


// ===== 销售端：待确认被动添加 =====
// 流程：销售输入手机号/微信号/昵称 → /api/leads/passive/candidates 返回 Top5 候选
//   → 选中绑定走 /api/leads/passive/bind；匹配不到则 /api/leads/passive/new。
function renderSalesPassiveLeads() {
  const candidates = state.passiveCandidates;
  const searchDone = !!state.passiveSearchDone;
  const employeesById = (state.employees || []).reduce((acc, item) => {
    acc[item.id] = item;
    return acc;
  }, {});
  const postsById = (Array.isArray(state.posts) ? state.posts : []).concat(Array.isArray(state.teamPosts) ? state.teamPosts : [])
    .reduce((acc, item) => {
      if (item && item.id) acc[item.id] = item;
      return acc;
    }, {});

  const renderCandidate = (item) => {
    const ownerName = employeesById[item.employeeId]?.name || item.employeeId || "未知";
    const postTitle = postsById[item.postId]?.title || item.postId || "未关联作品";
    const contact = item.contactInfo || "-";
    const status = item.status || item.addStatus || "-";
    const code = item.leadCode || item.id || "";
    const nickname = item.nickname || "未命名客户";
    const score = Number(item.score || 0);
    return `
      <div class="passive-candidate-card">
        <div class="meta">
          <h4>${nickname} <span class="muted">· ${code}</span></h4>
          <p>联系方式：${contact}</p>
          <p>来源运营：${ownerName}</p>
          <p>来源作品：${postTitle}</p>
          <p>当前状态：${status}</p>
          <p><span class="passive-score-badge">匹配分 ${score}</span></p>
        </div>
        <div>
          <button class="primary js-passive-bind" data-id="${item.id}" type="button">绑定此客资</button>
        </div>
      </div>
    `;
  };

  let candidatesHtml;
  if (!searchDone) {
    candidatesHtml = `<div class="empty">先输入客户信息查询候选</div>`;
  } else if (!Array.isArray(candidates) || candidates.length === 0) {
    candidatesHtml = `
      <div class="empty">未匹配到候选客资</div>
      <div><button class="primary" id="passiveCreateBtn" type="button">新建被动客资</button></div>
    `;
  } else {
    candidatesHtml = candidates.map(renderCandidate).join("");
  }

  const phoneVal = state._passiveQuery?.phone || "";
  const wechatVal = state._passiveQuery?.wechat || "";
  const nicknameVal = state._passiveQuery?.nickname || "";

  return `
    <div class="page-header page-header-rich">
      <div>
        <h2>待确认被动添加</h2>
        <p class="page-desc">客户主动加你？输入手机号 / 微信号 / 昵称，系统会找出疑似客资让你选择确认。</p>
      </div>
    </div>
    <div class="panel">
      <div class="filters filters-toolbar">
        <input id="passivePhoneInput" type="text" placeholder="手机号" value="${phoneVal}" />
        <input id="passiveWechatInput" type="text" placeholder="微信号 / 抖音号 / 小红书号" value="${wechatVal}" />
        <input id="passiveNicknameInput" type="text" placeholder="客户昵称" value="${nicknameVal}" />
        <button class="primary" id="passiveSearchBtn" type="button">查询候选</button>
      </div>
      <div class="passive-candidates">
        ${candidatesHtml}
      </div>
      <div class="passive-create-fallback" style="margin-top:16px;display:flex;align-items:center;gap:12px;">
        <span class="muted">匹配不到？</span>
        <button class="ghost" id="passiveCreateBtn2" type="button">新建被动客资</button>
      </div>
    </div>
  `;
}

async function searchPassiveCandidates() {
  const phone = document.getElementById("passivePhoneInput")?.value.trim() || "";
  const wechat = document.getElementById("passiveWechatInput")?.value.trim() || "";
  const nickname = document.getElementById("passiveNicknameInput")?.value.trim() || "";
  if (!phone && !wechat && !nickname) {
    setFlash("warn", "请填写信息", "至少填一个：手机号 / 微信号 / 昵称");
    renderApp();
    return;
  }
  const qs = new URLSearchParams({ phone, wechat, nickname }).toString();
  state.passiveCandidates = await api(`/api/leads/passive/candidates?${qs}`).catch(() => []);
  state.passiveSearchDone = true;
  state._passiveQuery = { phone, wechat, nickname };
  renderApp();
}

async function bindPassiveLead(leadId) {
  const q = state._passiveQuery || {};
  const contact = q.phone || q.wechat || "";
  const feedback = prompt("绑定备注（可填空）：", "客户主动加销售已通过");
  if (feedback === null) return;
  try {
    await api("/api/leads/passive/bind", {
      method: "POST",
      body: JSON.stringify({ leadId, contact, salesFeedback: feedback || "" })
    });
  } catch (e) {
    setFlash("warn", "绑定失败", e?.message || "请稍后重试");
    renderApp();
    return;
  }
  setFlash("success", "已绑定", "客资已绑定到当前销售并标记为被动添加。");
  state.passiveCandidates = null;
  state.passiveSearchDone = false;
  state._passiveQuery = null;
  await loadData();
  state.currentView = "sales-followups";
  renderApp();
}

function openPassiveCreateDialog() {
  const q = state._passiveQuery || {};
  const contact = q.phone || q.wechat || prompt("联系方式（必填）：");
  if (!contact) return;
  const nickname = q.nickname || prompt("客户昵称（可填空）：", "") || "";
  const platform = prompt("平台 xhs / douyin / unknown：", "unknown") || "unknown";
  const feedback = prompt("反馈备注：", "客户主动加销售已通过") || "";
  createPassiveLead({ contact, nickname, platform, feedback });
}

async function createPassiveLead({ contact, nickname, platform, feedback }) {
  try {
    await api("/api/leads/passive/new", {
      method: "POST",
      body: JSON.stringify({ contact, nickname, platform, salesFeedback: feedback })
    });
  } catch (e) {
    setFlash("warn", "新建失败", e?.message || "请稍后重试");
    renderApp();
    return;
  }
  setFlash("success", "新建被动客资", "已进入跟进看板，运营会确认来源后回填。");
  state.passiveCandidates = null;
  state.passiveSearchDone = false;
  state._passiveQuery = null;
  await loadData();
  state.currentView = "sales-followups";
  renderApp();
}

